def backfill_recipes_and_seed_catalogs(apps, schema_editor):
    Recipe = apps.get_model("recipes", "Recipe")
    RecipeCategory = apps.get_model("recipes", "RecipeCategory")
    RecipeTag = apps.get_model("recipes", "RecipeTag")
    Utensil = apps.get_model("recipes", "Utensil")

    for kind, order, slug, name in INITIAL_CATEGORIES:
        RecipeCategory.objects.get_or_create(slug=slug, defaults={"name": name, "kind": kind, "order": order})
    for kind, slug, name in INITIAL_TAGS:
        RecipeTag.objects.get_or_create(slug=slug, defaults={"name": name, "kind": kind})
    for slug, name in INITIAL_UTENSILS:
        Utensil.objects.get_or_create(slug=slug, defaults={"name": name})

    used_slugs = set(Recipe.objects.exclude(slug="").values_list("slug", flat=True))
    for recipe in Recipe.objects.all().order_by("id"):
        if not recipe.slug:
            base = slugify(recipe.name)[:200] or "receta"
            candidate = base
            counter = 2
            while candidate in used_slugs:
                suffix = f"-{counter}"
                candidate = f"{base[:220 - len(suffix)]}{suffix}"
                counter += 1
            used_slugs.add(candidate)
            recipe.slug = candidate

        # Recalcular caché nutricional inicial para recetas ya existentes en producción
        servings = max(1, int(recipe.servings or 1))
        total_w = 0.0
        totals = {
            "energy_kcal": 0.0,
            "proteins_g": 0.0,
            "carbohydrates_g": 0.0,
            "lipids_g": 0.0,
            "fiber_g": 0.0,
            "sodium_mg": 0.0,
            "potassium_mg": 0.0,
        }
        total_cg = 0.0
        for ing in recipe.ingredients.select_related("food").all():
            qty = float(ing.quantity_g)
            total_w += qty
            food = ing.food
            edible = 1.0 if food.edible_portion is None else max(0.0, min(100.0, float(food.edible_portion))) / 100.0
            factor = (qty / 100.0) * edible
            for field in totals:
                val = getattr(food, field)
                if val is not None:
                    totals[field] += float(val) * factor
            carbs = float(food.carbohydrates_g or 0)
            if carbs > 0 and food.glycemic_index is not None:
                total_cg += (float(food.glycemic_index) * (carbs * factor)) / 100.0

        recipe.cached_total_weight_g = Decimal(str(round(total_w, 2)))
        recipe.cached_kcal_per_serving = Decimal(str(round(totals["energy_kcal"] / servings, 2)))
        recipe.cached_proteins_per_serving = Decimal(str(round(totals["proteins_g"] / servings, 2)))
        recipe.cached_carbs_per_serving = Decimal(str(round(totals["carbohydrates_g"] / servings, 2)))
        recipe.cached_lipids_per_serving = Decimal(str(round(totals["lipids_g"] / servings, 2)))
        recipe.cached_fiber_per_serving = Decimal(str(round(totals["fiber_g"] / servings, 2)))
        recipe.cached_sodium_mg_per_serving = Decimal(str(round(totals["sodium_mg"] / servings, 2)))
        recipe.cached_potassium_mg_per_serving = Decimal(str(round(totals["potassium_mg"] / servings, 2)))
        recipe.cached_glycemic_load_per_serving = Decimal(str(round(total_cg / servings, 2)))
        recipe.save(update_fields=[
            "slug",
            "cached_total_weight_g",
            "cached_kcal_per_serving",
            "cached_proteins_per_serving",
            "cached_carbs_per_serving",
            "cached_lipids_per_serving",
            "cached_fiber_per_serving",
            "cached_sodium_mg_per_serving",
            "cached_potassium_mg_per_serving",
            "cached_glycemic_load_per_serving",
        ])


